import numpy as np

def score_ruin_nodes(distance_matrix, demands, capacity, route_ids, route_loads, route_dists, removal_savings, stagnation_ratio, iter_frac):
    savings = np.asarray(removal_savings, dtype=np.float64)
    n = int(savings.size)
    if n == 0:
        return np.zeros(0, dtype=np.float64)

    savings = np.nan_to_num(savings, nan=0.0, posinf=0.0, neginf=0.0)

    dm = np.asarray(distance_matrix, dtype=np.float64)
    depot_dist = np.zeros(0, dtype=np.float64)
    if dm.ndim == 2 and dm.shape[0] > 0 and dm.shape[1] > 1:
        take = min(n, dm.shape[1] - 1)
        depot_dist = dm[0, 1:1 + take]

    if depot_dist.size > 0:
        finite = np.isfinite(depot_dist)
        pos = depot_dist[finite & (depot_dist > 0.0)]
        if pos.size > 0:
            scale = float(np.median(pos))
        else:
            finite_vals = depot_dist[finite]
            if finite_vals.size > 0:
                scale = float(np.mean(finite_vals))
            else:
                scale = 0.0
    else:
        scale = 0.0

    if not np.isfinite(scale) or scale <= 0.0:
        if dm.size > 0:
            finite_dm = dm[np.isfinite(dm)]
            pos_all = finite_dm[finite_dm > 0.0]
            if pos_all.size > 0:
                scale = float(np.median(pos_all))
            else:
                scale = 1.0
        else:
            scale = 1.0
    scale = max(scale, 1e-12)

    cap = float(capacity)
    if not np.isfinite(cap) or cap <= 0.0:
        cap = 1.0

    removal_norm = savings / scale
    base = np.maximum(removal_norm, 0.0)

    loads = np.asarray(route_loads, dtype=np.float64)
    if loads.size != n:
        loads = np.zeros(n, dtype=np.float64)
    loads = np.nan_to_num(loads, nan=0.0, posinf=0.0, neginf=0.0)
    load_pressure = np.clip(loads / cap, 0.0, 1.0)

    stag = float(np.clip(stagnation_ratio, 0.0, 1.0)) if np.isfinite(stagnation_ratio) else 0.0
    prog = float(np.clip(iter_frac, 0.0, 1.0)) if np.isfinite(iter_frac) else 0.0

    alpha = 0.05 + 0.08 * stag + 0.04 * prog
    alpha = float(np.clip(alpha, 0.04, 0.17))
    pressure_term = np.minimum(alpha * load_pressure, 0.5 * base)

    score = removal_norm + pressure_term
    score = np.nan_to_num(score, nan=0.0, posinf=0.0, neginf=0.0)
    return np.asarray(score, dtype=np.float64)
